from html import escape
import json

BASE = [
 dict(title='Исходные данные совпадают', sender=1, receiver=2, label='синхронизация завершена', primary='product:42 = 120', replica='product:42 = 120', po='1000', ro='1000', client='Запись ещё не отправлена', detail='Реплика уже получила начальное состояние. Обе стороны находятся в одной истории репликации; база 0 уже выбрана. Смещение 1000 — условная начальная позиция, не число ключей.'),
 dict(title='Клиент отправляет изменение', sender=0, receiver=1, label='SET product:42 150', primary='product:42 = 120', replica='product:42 = 120', po='1000', ro='1000', client='Ожидает ответ SET', detail='На проводе RESP2 команда занимает 39 байт. Отправка клиентом ещё не означает исполнение сервером. В профиле Redis 7.2.0 других пользовательских записей нет. В ветви ожидающего WAIT ниже отдельно показан служебный GETACK; PING, SELECT и прочие служебные добавления в этот короткий интервал не попали.'),
 dict(title='Основной исполняет команду', sender=1, receiver=1, label='RAM: 120 → 150; backlog +39 Б', primary='product:42 = 150', replica='product:42 = 120', po='1039', ro='1000', client='Ожидает ответ SET', detail='Значение изменено в памяти основного. 39 байт добавлены в рассматриваемый поток и историю backlog. Данные для отправки реплике ещё не означают доставленные данные. Сохранение на диск здесь отключено.'),
 dict(title='Ответ клиенту доставлен раньше репликации', sender=1, receiver=0, label='+OK', primary='product:42 = 150', replica='product:42 = 120', po='1039', ro='1000', client='Получил OK для SET', detail='Обычный ответ SET не ждёт применения команды репликой. Это допустимый порядок событий, а не обязательный порядок каждого запроса. Отставание в выбранном интервале — 39 байт.'),
]
SCENARIOS={
 'loss': dict(title='Отказ до доставки реплике',steps=BASE+[
 dict(title='Основной становится недоступен',sender=1,receiver=1,label='ОТКАЗ; 39 Б не доставлены',primary='Недоступен; в RAM было 150',replica='product:42 = 120',po='1039 (недоступно)',ro='1000',client='Ранее получил OK',detail='В этом сценарии реплика не успела получить новую команду. Никакого ACK позиции 1039 от неё не было. Backlog на потерянном узле не доступен для восстановления.'),
 dict(title='Sentinel проводит процедуру переключения',sender=3,receiver=2,label='после обнаружения и выборов: повысить',primary='Недоступен',replica='Новый основной: product:42 = 120',po='—',ro='1000 до смены истории',client='Обновляет адрес и соединение',detail='Показан итог отдельной процедуры Sentinel: обнаружение, кворум, разрешение и выбор. Выбор роли не восстанавливает отсутствующие байты. Новая история репликации и её идентификаторы рассматриваются отдельно от старой позиции.'),
 dict(title='Чтение после переключения',sender=2,receiver=0,label='GET product:42 → 120',primary='Недоступен',replica='Новый основной: product:42 = 120',po='—',ro='история нового основного',client='Читает 120 вместо подтверждённых 150',detail='Приложение наблюдает потерю ранее подтверждённого изменения. Для восстановимого кэша можно перечитать источник. Для первичных данных это требуется учесть в RPO; переключение само по себе не гарантировало сохранение записи.')]),
 'delivered':dict(title='Доставка и подтверждение реплики',steps=BASE+[
 dict(title='Реплика получает и исполняет команду',sender=1,receiver=2,label='39 Б потока: SET product:42 150',primary='product:42 = 150',replica='product:42 = 150',po='1039',ro='1039',client='Уже получил OK',detail='Реплика разбирает и применяет поток. Теперь значения совпадают. Здесь подтверждена память реплики, а не дисковая устойчивость.'),
 dict(title='Реплика сообщает прогресс',sender=2,receiver=1,label='REPLCONF ACK 1039',primary='product:42 = 150',replica='product:42 = 150',po='1039',ro='1039',client='Может выполнить WAIT в том же соединении',detail='ACK сообщает позицию применённого потока. Основной может учитывать этот прогресс при ожидании WAIT. Сам ACK не является ответом непосредственно приложению.'),
 dict(title='WAIT возвращает число подтверждений',sender=1,receiver=0,label='WAIT 1 1000 → 1',primary='product:42 = 150',replica='product:42 = 150',po='1039',ro='1039',client='Проверил результат 1',detail='WAIT выполнен на том же соединении после SET. Требуемая одна реплика уже подтвердила позицию 1039, поэтому WAIT возвращает результат сразу и здесь не запрашивает новый GETACK. Результат не равен гарантии любого будущего failover и не заменяет fsync.')]),
 'timeout':dict(title='WAIT истёк до подтверждения',steps=BASE+[
 dict(title='Клиент начинает ожидание',sender=0,receiver=1,label='WAIT 1 1000',primary='product:42 = 150',replica='product:42 = 120',po='1039',ro='1000',client='Ждёт до 1000 мс',detail='Запрос относится к предшествующему SET того же соединения. У реплики пока нет нужного прогресса. Другая сессия клиента не должна использоваться вместо этой.'),
 dict(title='Основной запрашивает ACK',sender=1,receiver=2,label='REPLCONF GETACK *; +37 Б',primary='product:42 = 150',replica='product:42 = 120',po='1076',ro='1000',client='WAIT ждёт подтверждения позиции 1039',detail='В Redis 7.2.0 ожидающий WAIT запрашивает ACK через служебную команду потока. Её RESP2-представление занимает 37 байт: позиция основного 1039→1076. Целевая позиция предшествующего SET у этого клиента остаётся c->woff=1039. GETACK запрашивается при переходе WAIT к ожиданию, не самим событием истечения тайм-аута. В выбранной ветви доставка SET и GETACK реплике задержана за предел ожидания, ACK не приходит.'),
 dict(title='Тайм-аут не отменяет SET',sender=1,receiver=0,label='WAIT → 0',primary='product:42 = 150',replica='product:42 = 120',po='1076',ro='1000',client='Требование одной реплики не выполнено',detail='Клиент обязан проверить возвращённое число. 0 не означает rollback: значение 150 уже существует на основном. Повтор изменения требует собственной семантики, особенно для INCR.'),
 dict(title='Приложение выбирает дальнейшее действие',sender=0,receiver=0,label='ошибка гарантии / сверка / ограниченный повтор',primary='product:42 = 150',replica='product:42 = 120',po='1076',ro='1000',client='Не объявляет требуемую гарантию выполненной',detail='Решение зависит от операции: вернуть ошибку требуемой гарантии, проверить идентификатор операции или выполнить безопасный повтор. Нельзя автоматически считать недоставленное подтверждение отсутствием эффекта.')])
}


def render_replication():
    transcript=''
    for s in SCENARIOS.values():
        transcript+='<h4>'+escape(s['title'])+'</h4>'
        for i,row in enumerate(s['steps'],1):
            transcript+=f'<p><strong>{i}. {escape(row["title"])}</strong> — {escape(row["label"])}. {escape(row["detail"])}</p><p>Основной: {escape(row["primary"])}; реплика: {escape(row["replica"])}; позиции: {escape(row["po"])} / {escape(row["ro"])}; клиент: {escape(row["client"])}.</p>'
    return '<section id="cache-failover" class="interactive replication-lab"><h3>Передача одной записи: данные, сообщения и подтверждения</h3><p>Условия: product:42 меняется со 120 на 150. Профиль Redis 7.2.0: начальная синхронизация завершена, одна реплика, база 0 уже выбрана; persistence выключен, сервер не приостановлен. Других пользовательских записей нет. В ветви ожидающего WAIT служебный GETACK добавляет ещё 37 байт; PING, SELECT и других добавлений в поток в коротком выбранном интервале нет. Это выбранное чередование, не обязательное расписание живого сервера. Числа offset иллюстрируют только этот интервал. См. <a href="https://raw.githubusercontent.com/redis/redis/7.2.0/src/server.c">отправку GETACK</a> и <a href="https://raw.githubusercontent.com/redis/redis/7.2.0/src/replication.c">поток репликации и WAIT</a> в исходниках этой версии.</p><div data-replication-controls></div><div class="sequence-scroll"><svg data-sequence viewBox="0 0 1000 680" role="img" aria-label="Временная диаграмма репликации"></svg></div><div data-replication-state aria-live="polite"></div><details><summary>Все сценарии текстом и при печати</summary>'+transcript+'</details><script type="application/json" id="replication-scenarios">'+json.dumps(SCENARIOS,ensure_ascii=False)+'</script></section>'
